"use strict";(self.webpackChunkshutter_docs=self.webpackChunkshutter_docs||[]).push([[563],{7579:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>c,contentTitle:()=>s,default:()=>d,frontMatter:()=>i,metadata:()=>r,toc:()=>h});const r=JSON.parse('{"id":"shutter/research/shutterized_beacon_chain","title":"Shutterized Beacon Chain","description":"My document description","source":"@site/docs/shutter/research/shutterized_beacon_chain.md","sourceDirName":"shutter/research","slug":"/shutter/research/shutterized_beacon_chain","permalink":"/docs/shutter/research/shutterized_beacon_chain","draft":false,"unlisted":false,"editUrl":"https://github.com/shutter-network/shutter-docs/docs/shutter/research/shutterized_beacon_chain.md","tags":[],"version":"current","sidebarPosition":8,"frontMatter":{"title":"Shutterized Beacon Chain","description":"My document description","sidebar_label":"Shutterized Beacon Chain","sidebar_position":8},"sidebar":"shutterSidebar","previous":{"title":"The Road Towards an Encrypted Mempool On Ethereum","permalink":"/docs/shutter/research/the_road_towards_an_encrypted_mempool_on_ethereum"},"next":{"title":"The Viability of Integrating an Encrypted Mempool as Proposed by Shutter Into the OP Stack","permalink":"/docs/shutter/research/viability_integrating_enc_mempool_op_stack"}}');var o=n(4848),a=n(8453);const i={title:"Shutterized Beacon Chain",description:"My document description",sidebar_label:"Shutterized Beacon Chain",sidebar_position:8},s="Shutterized Beacon Chain",c={},h=[{value:"Acknowledgement",id:"acknowledgement",level:2},{value:"Summary",id:"summary",level:2},{value:"The problem",id:"the-problem",level:2},{value:"Requirements",id:"requirements",level:2},{value:"Shutter",id:"shutter",level:2},{value:"L1 Shutter in core protocol",id:"l1-shutter-in-core-protocol",level:2},{value:"Ciphertext transaction fees",id:"ciphertext-transaction-fees",level:3},{value:"Security guarantees",id:"security-guarantees",level:3},{value:"Changes to the implementation",id:"changes-to-the-implementation",level:3}];function l(e){const t={a:"a",code:"code",em:"em",h1:"h1",h2:"h2",h3:"h3",header:"header",img:"img",li:"li",p:"p",ul:"ul",...(0,a.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(t.p,{children:(0,o.jsxs)(t.em,{children:[(0,o.jsx)(t.a,{href:"https://ethresear.ch/t/shutterized-beacon-chain/12249",children:"Originally posted"})," at the Ethereum Research forum."]})}),"\n",(0,o.jsx)(t.header,{children:(0,o.jsx)(t.h1,{id:"shutterized-beacon-chain",children:"Shutterized Beacon Chain"})}),"\n",(0,o.jsxs)(t.h2,{id:"acknowledgement",children:[(0,o.jsx)(t.a,{href:"https://ethresear.ch/t/shutterized-beacon-chain/12249#acknowledgement-2"}),"Acknowledgement"]}),"\n",(0,o.jsxs)(t.p,{children:["We'd like to thank\xa0",(0,o.jsx)(t.a,{href:"https://ethresear.ch/u/mkoeppelmann",children:"@mkoeppelmann"}),"\xa0for coming up with the idea and collaborating with us on the proposal,\xa0",(0,o.jsx)(t.a,{href:"https://ethresear.ch/u/justindrake",children:"@JustinDrake"}),"\xa0for helpful discussions and creative ideas, as well as to Sebastian Faust and Stefan Dziembowski for designing Shutter's DKG protocol."]}),"\n",(0,o.jsxs)(t.h2,{id:"summary",children:[(0,o.jsx)(t.a,{href:"https://ethresear.ch/t/shutterized-beacon-chain/12249#summary-3"}),"Summary"]}),"\n",(0,o.jsxs)(t.ul,{children:["\n",(0,o.jsx)(t.li,{children:"MEV is an important problem, but it can be solved directly in an L1 beacon chain"}),"\n",(0,o.jsx)(t.li,{children:"Shutter provides a solution for that: A set of nodes compute an encryption key using a DKG protocol, let users encrypt their transactions with it, and release the decryption key once the encrypted transactions are in the chain."}),"\n",(0,o.jsx)(t.li,{children:"This technique can be applied to Ethereum-like beacon chains, by using the validator set to run the DKG protocol and introducing a scheduling mechanism for encrypted transactions."}),"\n"]}),"\n",(0,o.jsxs)(t.h2,{id:"the-problem",children:[(0,o.jsx)(t.a,{href:"https://ethresear.ch/t/shutterized-beacon-chain/12249#the-problem-4"}),"The problem"]}),"\n",(0,o.jsx)(t.p,{children:"Miner-extractable value (MEV) and front running are widely recognized to be among the final unsolved fundamental issues in the blockchain space. There are now hundreds of millions of dollars of documented MEV, most of which is tremendously harmful for users and traders. This problem will inevitably become more devastating over time and eventually could even pose a fatal obstacle on our community's path to mainstream adoption."}),"\n",(0,o.jsx)(t.p,{children:"The term MEV was coined by Phil Daian et al. and describes revenue that block producers can extract by selecting, injecting, ordering, and censoring transactions. The MEV extracted in 2020 alone was worth more than $314M --- and that is only a lower bound. Oftentimes, the MEV is not captured by the block producers themselves, but rather by independent entities using sophisticated bots."}),"\n",(0,o.jsx)(t.p,{children:"An important subset of MEV is the revenue extracted by so-called front running --- an attack that is illegal in traditional markets, but uncontrolled in the crypto space. A front runner watches the network for transactions that are worth targeting. As soon as they find one, they send their own transaction, trying to get included in the chain beforehand. They achieve this by paying a higher gas price, operating world-spanning network infrastructure, being a block producer themselves, or paying one via a back channel."}),"\n",(0,o.jsx)(t.p,{children:"The most frequent victims of front running attacks are traders on decentralized exchanges. Front running makes them suffer from worse prices instead of being fairly rewarded for the information they provide to the market. On the other side, front runners siphon off profits from their victims in a nearly risk-free fashion without contributing anything useful to the system. A simple example of this are arbitrage transactions benefitting from the price difference of the same asset on two different DEX's. Front runners regularly copy these kinds of transactions from other market participants and execute them earlier, reaping the rewards, whereas the original trader comes away empty-handed."}),"\n",(0,o.jsx)(t.p,{children:"Besides exchanges, many other applications can be affected as well, including bounty distributions and auctions. Importantly, because they rely on voting, governance systems, which represent a large and fast-growing field within Ethereum, are prone to front running and could face significant challenges without a system that protects against these types of attacks."}),"\n",(0,o.jsx)(t.p,{children:"In traditional finance, front running can be curbed (somewhat) via regulation or oversight by various trusted intermediaries and operators. In permissionless, decentralized systems this is not the case, so it might be a strategic blocker to mainstream crypto adoption."}),"\n",(0,o.jsxs)(t.h2,{id:"requirements",children:[(0,o.jsx)(t.a,{href:"https://ethresear.ch/t/shutterized-beacon-chain/12249#requirements-5"}),"Requirements"]}),"\n",(0,o.jsx)(t.p,{children:"We believe the beacon chains should be MEV protected for their users with no overhead or changes in terms of user experience. This protection should also come with no additional security guarantees, or, should at least fallback to the standard non-MEV protected functionning in case the added security assumptions fail. Lastly, it should work with a similar decentralization level as the consensus protocol."}),"\n",(0,o.jsxs)(t.h2,{id:"shutter",children:[(0,o.jsx)(t.a,{href:"https://ethresear.ch/t/shutterized-beacon-chain/12249#shutter-6"}),"Shutter"]}),"\n",(0,o.jsx)(t.p,{children:"Shutter allows users to send encrypted transactions in a way that protects them from front runners on their path through the dark forest (the metaphorical hunting ground of front runners that each transaction must cross). For example, a trader could use Shutter to make their order opaque to front runners, which means attackers can neither determine if it is a buy or a sell order, nor which tokens are being exchanged, or at which price. The system will only decrypt and execute a transaction after it has left the dark forest, i.e. after the execution environment of the transaction has been determined."}),"\n",(0,o.jsx)(t.p,{children:'The keys for encryption and decryption are provided by a group of special nodes called keypers. Keypers regularly produce encryption keys by running a distributed key generation (DKG) protocol. Later, they publish the corresponding decryption key. The protocol uses threshold cryptography --- a technique enabling a group of key holders to provide a cryptographic lock that can only be opened if at least a certain number of the members collaborate. This ensures that neither a single party, nor a colluding minority of keypers, can decrypt anything early or sabotage the protocol to stop it from executing transactions. As long as a certain number of keypers (the "threshold") is well-behaved, the protocol functions properly.'}),"\n",(0,o.jsxs)(t.h2,{id:"l1-shutter-in-core-protocol",children:[(0,o.jsx)(t.a,{href:"https://ethresear.ch/t/shutterized-beacon-chain/12249#l1-shutter-in-core-protocol-7"}),"L1 Shutter in core protocol"]}),"\n",(0,o.jsx)(t.p,{children:"We have already developed on-chain shutter, a mechanism to protect individual smart contracts from ordering attacks on L1, but it has the drawback of breaking composability. We are further working on implementing shutter directly inside roll-ups. Here we will describe a design to integrate the shutter system as part of Ethereum-like beacon chains. This has the benefit of being completely abstracted away from the user, and conserving composability."}),"\n",(0,o.jsx)(t.p,{children:"As in every shutter system, the protocol needs a set of keypers. The keyper set is selected among chain validators by similar procedures selecting committees or block producers, except they would be selected much less frequently (e.g. once a day). Keypers use the beacon chain to generate a shared eon key. The eon public key will be made available to users to encrypt their transactions."}),"\n",(0,o.jsx)(t.p,{children:"Block producers collect encrypted as well as plaintext transactions for a block. They include in their blocks the plaintext transactions to be executed, while encrypted transactions are scheduled for a future block height."}),"\n",(0,o.jsx)(t.p,{children:"After a block is produced, the keypers should generate the decryption key allowing to decrypt the transactions scheduled for that block. The following block must include the decryption key to be considered valid. The post state of the block is computed by executing first the encrypted transactions scheduled for that block, before executing the plaintext transactions included in that block."}),"\n",(0,o.jsx)(t.p,{children:"The execution order and context (block number, timestamp, etc ...) is determined by the order of inclusion of ciphertext transactions and the context of the previous block. The context of execution being determined before the decryption of the transaction, it is impossible to use information about the transaction data to extract MEV. It also prevents side-channel information that could be used to optimistically front-run a transaction."}),"\n",(0,o.jsx)(t.p,{children:(0,o.jsx)(t.img,{alt:"Group 1",src:n(9239).A+"",width:"635",height:"189"})}),"\n",(0,o.jsxs)(t.h3,{id:"ciphertext-transaction-fees",children:[(0,o.jsx)(t.a,{href:"https://ethresear.ch/t/shutterized-beacon-chain/12249#ciphertext-transaction-fees-8"}),"Ciphertext transaction fees"]}),"\n",(0,o.jsx)(t.p,{children:"Block producers need to somehow ensure that encrypted transactions are worth including in a block, i.e. that they can pay for a transacion fee, without knowing the transaction data. If the fee would be paid at time of execution, the block producer would not be guaranteed to be paid, since the account could be depleted in between inclusion and execution."}),"\n",(0,o.jsxs)(t.p,{children:["Therefore, encrypted transactions justify their inclusion by providing a signed\xa0",(0,o.jsx)(t.code,{children:"envelope"}),"\xa0paying the fees at the moment of its inclusion in the chain. The envelope includes the fields:\xa0",(0,o.jsx)(t.code,{children:"gas consumption"}),",\xa0",(0,o.jsx)(t.code,{children:"gas price"}),", and a signature on these fields, allowing to recover the\xa0",(0,o.jsx)(t.code,{children:"fee payer"}),"\xa0address. The fee will be paid on inclusion of the ciphertext transaction to the block producer, i.e. not at the time of execution. The gas consumption of the ciphertext transaction counts towards the gas limit of the block it was included in."]}),"\n",(0,o.jsxs)(t.p,{children:["The traditional\xa0",(0,o.jsx)(t.code,{children:"gas limit"}),"\xa0needs to be replaced with\xa0",(0,o.jsx)(t.code,{children:"gas consumption"}),", meaning that the user will pay for all the gas it plans to use, even if it uses only part of it at the time the transaction is decrypted and applied. This is necessary for the fee to be paid at the time of the transaction inclusion in the chain. This prevents blocks producers from having to include a transaction with an incredibly high\xa0",(0,o.jsx)(t.code,{children:"gas limit"}),"\xa0(taking the place of other transactions and their fees) that decrypts to a transaction with very little\xa0",(0,o.jsx)(t.code,{children:"gas used"}),"\xa0(and fees)."]}),"\n",(0,o.jsx)(t.p,{children:"The other drawback of using envelope transaction is that meta-data of the transaction are leaked, i.e. the fee payer and gas price / upper limit of consumption are known. Potentially, a small part of MEV can still be extracted using this leaked information."}),"\n",(0,o.jsx)(t.p,{children:"It has been pointed out that a zk-SNARK approach could be envisonned to solve this fee payment problem as well, and prevent the leaking meta-data information."}),"\n",(0,o.jsxs)(t.h3,{id:"security-guarantees",children:[(0,o.jsx)(t.a,{href:"https://ethresear.ch/t/shutterized-beacon-chain/12249#security-guarantees-9"}),"Security guarantees"]}),"\n",(0,o.jsx)(t.p,{children:"The eon public key and decryption keys generated by keypers require a t out of n threshold of honest participants. The parameters t and n can be played with to adapt the protocol. The higher t, the harder for keypers to collude and decrypt transactions too early (allowing MEV extraction). On the other hand, a lower t will guarantee that the decryption key is released in a timely manner."}),"\n",(0,o.jsx)(t.p,{children:"To enforce decryption and application of ciphertext transactions, we have to enforce inclusion of the decryption key in each block. In these conditions, if keypers turn offline or refuse to produce a decryption key, the block production will halt."}),"\n",(0,o.jsx)(t.p,{children:"We can mitigate the liveness influence of keypers by allowing to produce a block without a decryption key if there is no encrypted transaction scheduled for execution. In case keypers go offline, the chain would recover by forking away the blocks with encrypted transactions and produce blocks only with plaintext transactions."}),"\n",(0,o.jsx)(t.p,{children:"We can also recover liveness by stating that if no block is produced during n slots (due to not having the decryption key), the next block does not need to include a decryption key, and decrypted transactions are ignored. This will fall back to the legacy non-MEV protected functionning of the chain."}),"\n",(0,o.jsxs)(t.h3,{id:"changes-to-the-implementation",children:[(0,o.jsx)(t.a,{href:"https://ethresear.ch/t/shutterized-beacon-chain/12249#changes-to-the-implementation-10"}),"Changes to the implementation"]}),"\n",(0,o.jsx)(t.p,{children:"The keyper software has already been developed, as well as all the encryption / decryption logic. We also developed the logic allowing a block producer (or collator / sequencer) to commit to a batch of encrypted transactions, signaling to the keypers that it is now safe to release the decryption key."}),"\n",(0,o.jsx)(t.p,{children:"What needs to be done is to change the rules that define correctness of a block in client implementations, as well as the rules for execution of transactions. The interface for submission of transaction to the client has to be redefined. Lastly, tools and plugins will likely have to be written to allow dapps to seamlessly integrate with an MEV protected chain requiring encryption of transactions with the public eon key."})]})}function d(e={}){const{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(l,{...e})}):l(e)}},8453:(e,t,n)=>{n.d(t,{R:()=>i,x:()=>s});var r=n(6540);const o={},a=r.createContext(o);function i(e){const t=r.useContext(a);return r.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function s(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:i(e.components),r.createElement(a.Provider,{value:t},e.children)}},9239:(e,t,n)=>{n.d(t,{A:()=>r});const r="data:image/png;base64,"}}]);